begin;
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create type public.tenant_status as enum ('draft','submitted','needs_information','under_review','approved','active','rejected','suspended','expired','revoked');
create type public.subscription_status as enum ('pending_verification','verification_approved','invoice_pending','payment_pending','active','grace','past_due','suspended','cancelled','expired');
create type public.invoice_status as enum ('draft','open','paid','void','past_due');
create type public.outbox_status as enum ('queued','processing','sent','delivered','failed','requires_review');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.platform_users (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id), mfa_required boolean not null default true, active boolean not null default true, created_at timestamptz not null default now());
create table public.platform_roles (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, permissions text[] not null default '{}');
create table public.platform_user_roles (platform_user_id uuid references public.platform_users(id) on delete cascade, role_id uuid references public.platform_roles(id) on delete restrict, primary key(platform_user_id,role_id));
create table public.tenants (id uuid primary key default gen_random_uuid(), legal_name text not null, trading_name text, pacra_number text not null unique, tpin text not null, status public.tenant_status not null default 'draft', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tenant_status_history (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), from_status public.tenant_status, to_status public.tenant_status not null, reason text, changed_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.tenant_roles (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), code text not null, name text not null, unique(tenant_id,code));
create table public.tenant_memberships (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), profile_id uuid not null references public.profiles(id), role_id uuid not null references public.tenant_roles(id), active boolean not null default true, created_at timestamptz not null default now(), unique(tenant_id,profile_id));
create table public.tenant_role_permissions (role_id uuid not null references public.tenant_roles(id) on delete cascade, permission text not null, primary key(role_id,permission));
create table public.tenant_verification_profiles (id uuid primary key default gen_random_uuid(), tenant_id uuid not null unique references public.tenants(id), physical_address text not null, postal_address text, primary_contact jsonb not null default '{}', directors jsonb not null default '[]', status public.tenant_status not null default 'draft', submitted_at timestamptz, updated_at timestamptz not null default now());
create table public.tenant_licences (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), licence_type text not null, licence_number text not null, issuing_authority text not null, authorised_name text not null, authorised_address text not null, issue_date date not null, expiry_date date not null, status text not null default 'pending' check(status in('pending','accepted','rejected','expired','revoked')), unique(tenant_id,licence_number), check(expiry_date>=issue_date));
create table public.tenant_licence_documents (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), licence_id uuid not null references public.tenant_licences(id), storage_path text not null, file_hash text not null, review_status text not null default 'uploaded', uploaded_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), unique(tenant_id,file_hash));
create table public.verification_reviews (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), reviewer_id uuid not null references public.platform_users(id), status text not null, notes text, created_at timestamptz not null default now());
create table public.verification_decisions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), review_id uuid not null references public.verification_reviews(id), decision text not null check(decision in('request_information','approve','reject','suspend')), reason text not null, decided_by uuid not null references public.platform_users(id), created_at timestamptz not null default now());
create table public.compliance_declarations (id uuid primary key default gen_random_uuid(), code text not null, version int not null, content_hash text not null, effective_at timestamptz not null, unique(code,version));
create table public.legal_document_versions (id uuid primary key default gen_random_uuid(), document_type text not null, version int not null, content_hash text not null, effective_at timestamptz not null, unique(document_type,version));
create table public.legal_acceptances (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), profile_id uuid not null references public.profiles(id), legal_document_id uuid references public.legal_document_versions(id), declaration_id uuid references public.compliance_declarations(id), accepted_at timestamptz not null default now(), ip inet, user_agent text, check((legal_document_id is null)<>(declaration_id is null)));

create table public.subscription_plans (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.plan_versions (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.subscription_plans(id), version int not null, monthly_price_minor bigint not null check(monthly_price_minor>=0), annual_price_minor bigint not null check(annual_price_minor>=0), currency char(3) not null default 'ZMW' check(currency='ZMW'), effective_from date not null, effective_to date, publicly_available boolean not null default false, grace_days int not null default 0 check(grace_days between 0 and 90), unique(plan_id,version));
create table public.plan_entitlements (id uuid primary key default gen_random_uuid(), plan_version_id uuid not null references public.plan_versions(id) on delete cascade, entitlement text not null, limit_value bigint, enabled boolean not null default true, unique(plan_version_id,entitlement));
create table public.tenant_subscriptions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), plan_version_id uuid not null references public.plan_versions(id), status public.subscription_status not null default 'pending_verification', billing_period text not null check(billing_period in('monthly','annual')), starts_at timestamptz, ends_at timestamptz, grace_ends_at timestamptz, created_at timestamptz not null default now());
create table public.subscription_invoices (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), subscription_id uuid not null references public.tenant_subscriptions(id), invoice_number text not null unique, status public.invoice_status not null default 'open', amount_minor bigint not null check(amount_minor>=0), currency char(3) not null default 'ZMW' check(currency='ZMW'), issued_at timestamptz not null default now(), due_at timestamptz not null, paid_at timestamptz, document_path text, document_hash text);
create table public.subscription_invoice_lines (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), invoice_id uuid not null references public.subscription_invoices(id), description text not null, quantity int not null default 1 check(quantity>0), unit_amount_minor bigint not null check(unit_amount_minor>=0), total_minor bigint generated always as (quantity*unit_amount_minor) stored);
create table public.subscription_payment_attempts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), invoice_id uuid not null references public.subscription_invoices(id), idempotency_key text not null unique, amount_minor bigint not null check(amount_minor>=0), currency char(3) not null default 'ZMW', status text not null, created_at timestamptz not null default now());
create table public.lenco_collections (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), payment_attempt_id uuid not null unique references public.subscription_payment_attempts(id), internal_reference text not null unique, lenco_reference text unique, provider text not null check(provider in('mtn','airtel','zamtel')), phone_e164 text not null, amount_minor bigint not null check(amount_minor>=0), currency char(3) not null default 'ZMW', status text not null, last_queried_at timestamptz, created_at timestamptz not null default now());
create table public.lenco_webhook_events (id uuid primary key default gen_random_uuid(), event_id text unique, reference text not null, payload jsonb not null, payload_hash text not null, signature_valid boolean not null, processed_at timestamptz, processing_error text, created_at timestamptz not null default now(), unique(reference,payload_hash));
create table public.subscription_receipts (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), invoice_id uuid not null unique references public.subscription_invoices(id), receipt_number text not null unique, amount_minor bigint not null check(amount_minor>=0), currency char(3) not null default 'ZMW', lenco_reference text not null, paid_at timestamptz not null, document_path text, document_hash text not null, created_at timestamptz not null default now());
create table public.subscription_adjustments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), invoice_id uuid not null references public.subscription_invoices(id), type text not null check(type in('credit','void','reversal')), amount_minor bigint not null, reason text not null, created_by uuid not null references public.platform_users(id), created_at timestamptz not null default now());
create table public.subscription_status_history (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), subscription_id uuid not null references public.tenant_subscriptions(id), from_status public.subscription_status, to_status public.subscription_status not null, reason text not null, created_at timestamptz not null default now());

create table public.support_cases (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id), subject text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.support_access_grants (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), case_id uuid not null references public.support_cases(id), platform_user_id uuid not null references public.platform_users(id), reason text not null, starts_at timestamptz not null, expires_at timestamptz not null, approved_by uuid references public.platform_users(id), check(expires_at>starts_at));
create table public.audit_events (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id), actor_profile_id uuid references public.profiles(id), entity_type text not null, entity_id uuid, action text not null, reason text, ip inet, user_agent text, correlation_id uuid not null default gen_random_uuid(), metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.job_runs (id uuid primary key default gen_random_uuid(), job_type text not null, status text not null, correlation_id uuid not null default gen_random_uuid(), started_at timestamptz not null default now(), completed_at timestamptz, error_summary text);
create table public.integration_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id), provider text not null, operation text not null, status text not null, correlation_id uuid not null, safe_metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.email_outbox (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id), message_type text not null, recipient text not null, subject text not null, template_version int not null, payload jsonb not null, idempotency_key text not null unique, status public.outbox_status not null default 'queued', attempt_count int not null default 0, next_attempt_at timestamptz not null default now(), provider_message_id text unique, last_error text, created_at timestamptz not null default now(), sent_at timestamptz);
create table public.email_messages (id uuid primary key default gen_random_uuid(), outbox_id uuid not null unique references public.email_outbox(id), provider_message_id text not null unique, status public.outbox_status not null, created_at timestamptz not null default now());
create table public.email_webhook_events (id uuid primary key default gen_random_uuid(), provider_event_id text not null unique, provider_message_id text not null, event_type text not null, payload_hash text not null, received_at timestamptz not null default now());

create or replace function private.is_platform_user() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.platform_users pu where pu.profile_id=auth.uid() and pu.active)$$;
create or replace function private.is_tenant_member(target_tenant uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.tenant_memberships m where m.tenant_id=target_tenant and m.profile_id=auth.uid() and m.active)$$;
create or replace function private.tenant_can_operate(target_tenant uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.tenants t join public.tenant_verification_profiles v on v.tenant_id=t.id join public.tenant_licences l on l.tenant_id=t.id and l.status='accepted' join public.tenant_subscriptions s on s.tenant_id=t.id where t.id=target_tenant and t.status='active' and v.status='approved' and l.expiry_date>=current_date and s.status in('active','grace'))$$;
revoke all on all functions in schema private from public,anon,authenticated;
grant execute on function private.is_platform_user() to authenticated;
grant execute on function private.is_tenant_member(uuid) to authenticated;
grant execute on function private.tenant_can_operate(uuid) to authenticated;

do $$ declare table_name text; begin for table_name in select unnest(array['profiles','platform_users','platform_roles','platform_user_roles','tenants','tenant_status_history','tenant_roles','tenant_memberships','tenant_role_permissions','tenant_verification_profiles','tenant_licences','tenant_licence_documents','verification_reviews','verification_decisions','compliance_declarations','legal_document_versions','legal_acceptances','subscription_plans','plan_versions','plan_entitlements','tenant_subscriptions','subscription_invoices','subscription_invoice_lines','subscription_payment_attempts','lenco_collections','lenco_webhook_events','subscription_receipts','subscription_adjustments','subscription_status_history','support_cases','support_access_grants','audit_events','job_runs','integration_logs','email_outbox','email_messages','email_webhook_events']) loop execute format('alter table public.%I enable row level security',table_name); end loop; end $$;
create policy profiles_self on public.profiles for select to authenticated using(id=auth.uid());
create policy tenants_member_read on public.tenants for select to authenticated using(private.is_tenant_member(id) or private.is_platform_user());
create policy verification_member_read on public.tenant_verification_profiles for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy licences_member_read on public.tenant_licences for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy licence_docs_member_read on public.tenant_licence_documents for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy subscriptions_member_read on public.tenant_subscriptions for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy invoices_member_read on public.subscription_invoices for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy receipts_member_read on public.subscription_receipts for select to authenticated using(private.is_tenant_member(tenant_id) or private.is_platform_user());
create policy plans_authenticated_read on public.subscription_plans for select to authenticated using(active);
create policy plan_versions_authenticated_read on public.plan_versions for select to authenticated using(publicly_available and effective_from<=current_date and (effective_to is null or effective_to>=current_date));
create policy plan_entitlements_authenticated_read on public.plan_entitlements for select to authenticated using(exists(select 1 from public.plan_versions v where v.id=plan_version_id and v.publicly_available));
create policy audit_scoped_read on public.audit_events for select to authenticated using((tenant_id is not null and private.is_tenant_member(tenant_id)) or private.is_platform_user());

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('tenant-licences','tenant-licences',false,10485760,array['application/pdf','image/png','image/jpeg']),('platform-billing','platform-billing',false,10485760,array['application/pdf']) on conflict(id) do nothing;
create policy tenant_licence_storage_read on storage.objects for select to authenticated using(bucket_id='tenant-licences' and private.is_tenant_member(((storage.foldername(name))[1])::uuid));
create policy billing_storage_read on storage.objects for select to authenticated using(bucket_id='platform-billing' and private.is_tenant_member(((storage.foldername(name))[1])::uuid));

create index tenant_memberships_profile_idx on public.tenant_memberships(profile_id,tenant_id) where active;
create index invoices_tenant_status_idx on public.subscription_invoices(tenant_id,status,issued_at desc);
create index collections_status_idx on public.lenco_collections(status,created_at) where status not in('successful','failed');
create index outbox_due_idx on public.email_outbox(status,next_attempt_at) where status in('queued','failed');
create index audit_tenant_created_idx on public.audit_events(tenant_id,created_at desc);
commit;
